        body: `流水算は「川の流れが船の速さに影響する」問題です。上りと下りで公式が逆になる点が最大の注意点です。

■ 基本公式
　下りの速さ ＝ 静水時の速さ ＋ 川の流れの速さ
　上りの速さ ＝ 静水時の速さ － 川の流れの速さ

【例】静水時の速さが時速15km、川の流れの速さが時速3kmの船がある。この船の下りの速さと上りの速さは？

下りの速さ＝15＋3＝18km/h
上りの速さ＝15－3＝12km/h

★ ポイント：「下り」は川の流れる方向に進むので流れの分だけ速くなり（足す）、「上り」は流れに逆らって進むので流れの分だけ遅くなります（引く）。「川を下る＝流れに乗る＝速い」とイメージすると覚えやすいです。

⚠ 注意：上りと下りを逆に覚えて、上りに流れを足し、下りから流れを引いてしまうミスが非常に多いです。「下る」「上る」という漢字のイメージ（下りは流れに乗って楽、上りは流れに逆らって大変）で覚えましょう。`,
