        body: `■ 川の水そのものが動いている
川の流れが時速 3km ということは、水の上に浮いているだけの物（笹舟）が 1 時間に 3km 下流へ運ばれるという意味です。船は水の上を自分の力で進むので、岸から見た船の速さは「水に対する船の速さ（静水時の速さ）」と「水そのものの速さ（流れ）」を合わせたものになります。**下りは船の進む向きと水の動く向きが同じ**なので足し算（15＋3＝18）、**上りは向きが反対**なので引き算（15−3＝12）です。

■ 動く歩道で考える
動く歩道の上を歩くと、歩道の動きと同じ向きなら速く進み、逆向きに歩くと遅くなります。川の流れは「動く歩道」、静水時の速さは「自分の歩く速さ」。**同じ向きなら足す、逆向きなら引く**という 1 つの考え方で、下り・上りの両方が説明できます。

■ 逆に覚えてしまう理由と防ぎ方
ひっかけの「上り 18km・下り 12km」は、足す・引くを逆にしたものです。「下る」は流れに乗って楽（速い）、「上る」は流れに逆らって大変（遅い）——**下りのほうが必ず速い**ので、2 つの数を出したら大きいほうが下りになっているかを見るだけで、逆転は防げます。

■ 上りにかかる時間は上りの速さで
静水時 18km/h・流れ 2km/h の船が 24km 上るとき、上りの速さは 18−2＝16km/h なので 24÷16＝1.5 時間。ひっかけの 1.2 時間は 24÷(18＋2)＝24÷20 で、下りの速さを使ったものです。「上る」と書いてあるので引き算。**問題文の「上る・下る」を式の前に丸で囲む**と、取りちがえが減ります。

■ 静水時の速さは「本来の力」
静水時の速さは、流れの無い池で船が出せる速さで、川では直接は現れません。川で測れるのは下りと上りの速さだけで、静水時の速さはその「真ん中」にあります（18 と 12 の真ん中が 15）。この見方は次の単元（半分・半分の公式）につながります。

★ ここがポイント：船の速さは**水に対する速さ（静水時）＋ 水そのものの速さ（流れ）**。同じ向きの下りは**足す**、逆向きの上りは**引く**。**下りのほうが必ず速い**ので、大きいほうが下りになっているかで逆転を防ぐ。`,
